			this.shimmerWet = false;
			this.SpawnedFromStatue = false;
			this.extraValue = 0;
			this.shimmerTransparency = 0f;
			this.lookForHomeTimeout = 0;
			Array.Clear(this.buffTime, 0, this.buffTime.Length);
			Array.Clear(this.buffType, 0, this.buffType.Length);
			Array.Clear(this.playerInteraction, 0, this.playerInteraction.Length);
			if (this.whoAmI >= Main.maxNPCs)
			{
				return;
			}
			PortalHelper.ResetNPCSlotData(this.whoAmI);
